-- 2025 sectors and sub-sectors of the SEPLAT EHOR planting site (project T4L), from
-- SEPLAT_EHOR_2025_Sectors_and_Subsectors_FULL.kml (Minna/UTM 31N converted to WGS84). 26 sectors, 239 sub-sectors:
-- sectors 1-18 (portions A and D) were surveyed; sectors 19-26 (portions B and C) are a computed planning grid
-- (10 ha sectors, 1 ha sub-sectors) whose pegs are still to be set in the field, so their GPS is approximate.
--
-- Sectors S1-S26 and their sub-sectors SS1-SSn are updated in place when they exist, so every tree keeps the sector and
-- sub-sector it was recorded in; missing ones are created. Other 2025 areas are removed only when nothing refers to
-- them. Does nothing when the project or its 2025 planting year does not exist. Safe to run again.

CREATE TEMP TABLE plan25_sectors (n int, portion text, surveyed boolean, outline text) ON COMMIT DROP;

CREATE TEMP TABLE plan25_sub_sectors (sector_n int, n int, outline text) ON COMMIT DROP;

DO $$
DECLARE
  pid uuid;
  yid uuid;
  kept int;
BEGIN
  SELECT id INTO pid FROM projects WHERE short_code = 'T4L';
  IF pid IS NULL THEN RAISE NOTICE '2025 sectoring: project T4L not found, nothing changed'; RETURN; END IF;
  SELECT id INTO yid FROM planting_years WHERE project_id = pid AND year_label = '2025';
  IF yid IS NULL THEN RAISE NOTICE '2025 sectoring: planting year 2025 not found, nothing changed'; RETURN; END IF;

  UPDATE sectors s SET
      name = 'Sector ' || p.n,
      description = 'Portion ' || p.portion || CASE WHEN p.surveyed THEN ' · surveyed' ELSE ' · approximate GPS: computed planning grid, pegs to be set' END,
      boundary_geometry = ST_SetSRID(ST_GeomFromText(p.outline), 4326),
      reference_latitude = ST_Y(ST_PointOnSurface(ST_GeomFromText(p.outline))),
      reference_longitude = ST_X(ST_PointOnSurface(ST_GeomFromText(p.outline))),
      active = true, updated_at = now()
    FROM plan25_sectors p
   WHERE s.project_id = pid AND s.planting_year_id = yid AND s.short_code = 'S' || p.n;
  SELECT pid, yid, 'Sector ' || p.n, 'S' || p.n,
         'Portion ' || p.portion || CASE WHEN p.surveyed THEN ' · surveyed' ELSE ' · approximate GPS: computed planning grid, pegs to be set' END,
         ST_Y(ST_PointOnSurface(ST_GeomFromText(p.outline))), ST_X(ST_PointOnSurface(ST_GeomFromText(p.outline))),
         ST_SetSRID(ST_GeomFromText(p.outline), 4326)
    FROM plan25_sectors p
   WHERE NOT EXISTS (SELECT 1 FROM sectors s WHERE s.project_id = pid AND s.planting_year_id = yid AND s.short_code = 'S' || p.n);

  UPDATE sub_sectors ss SET
      name = 'Sub-sector ' || p.n,
      description = CASE WHEN ps.surveyed THEN 'Portion ' || ps.portion || ' · surveyed' ELSE 'Portion ' || ps.portion || ' · approximate GPS' END,
      boundary_geometry = ST_SetSRID(ST_GeomFromText(p.outline), 4326),
      reference_latitude = ST_Y(ST_PointOnSurface(ST_GeomFromText(p.outline))),
      reference_longitude = ST_X(ST_PointOnSurface(ST_GeomFromText(p.outline))),
      active = true, updated_at = now()
    FROM plan25_sub_sectors p JOIN plan25_sectors ps ON ps.n = p.sector_n, sectors s
   WHERE s.project_id = pid AND s.planting_year_id = yid AND s.short_code = 'S' || p.sector_n
     AND ss.sector_id = s.id AND ss.short_code = 'SS' || p.n;
  SELECT s.id, pid, 'Sub-sector ' || p.n, 'SS' || p.n,
         CASE WHEN ps.surveyed THEN 'Portion ' || ps.portion || ' · surveyed' ELSE 'Portion ' || ps.portion || ' · approximate GPS' END,
         ST_Y(ST_PointOnSurface(ST_GeomFromText(p.outline))), ST_X(ST_PointOnSurface(ST_GeomFromText(p.outline))),
         ST_SetSRID(ST_GeomFromText(p.outline), 4326)
    FROM plan25_sub_sectors p JOIN plan25_sectors ps ON ps.n = p.sector_n
    JOIN sectors s ON s.project_id = pid AND s.planting_year_id = yid AND s.short_code = 'S' || p.sector_n
   WHERE NOT EXISTS (SELECT 1 FROM sub_sectors ss WHERE ss.sector_id = s.id AND ss.short_code = 'SS' || p.n);

  DELETE FROM sub_sectors ss USING sectors s
   WHERE ss.sector_id = s.id AND s.project_id = pid AND s.planting_year_id = yid
     AND NOT EXISTS (SELECT 1 FROM plan25_sub_sectors p WHERE s.short_code = 'S' || p.sector_n AND ss.short_code = 'SS' || p.n)
     AND NOT EXISTS (SELECT 1 FROM trees t WHERE t.sub_sector_id = ss.id)
     AND NOT EXISTS (SELECT 1 FROM user_project_assignments a WHERE a.sub_sector_id = ss.id);
  DELETE FROM sectors s
   WHERE s.project_id = pid AND s.planting_year_id = yid
     AND NOT EXISTS (SELECT 1 FROM plan25_sectors p WHERE s.short_code = 'S' || p.n)
     AND NOT EXISTS (SELECT 1 FROM sub_sectors ss WHERE ss.sector_id = s.id)
     AND NOT EXISTS (SELECT 1 FROM trees t WHERE t.sector_id = s.id)
     AND NOT EXISTS (SELECT 1 FROM user_project_assignments a WHERE a.sector_id = s.id);

  SELECT count(*) INTO kept FROM sub_sectors ss JOIN sectors s ON s.id = ss.sector_id
   WHERE s.project_id = pid AND s.planting_year_id = yid
     AND NOT EXISTS (SELECT 1 FROM plan25_sub_sectors p WHERE s.short_code = 'S' || p.sector_n AND ss.short_code = 'SS' || p.n);
  RAISE NOTICE '2025 sectoring applied; % earlier 2025 sub-sector(s) outside the plan kept because records use them', kept;
END $$;
